// ─── Prediction Helper ────────────────────────────────
int rf_predict(float* input, float* confidence) {
    double output[5];
    score(input, output);
    
    // Convert votes to probabilities
    double total = 0.0;
    for (int i = 0; i < 5; i++) total += output[i];
    
    int best = 0;
    double best_prob = 0.0;
    for (int i = 0; i < 5; i++) {
        double prob = (total > 0) ? output[i] / total : 0.0;
        if (prob > best_prob) {
            best_prob = prob;
            best = i;
        }
    }
    *confidence = (float)best_prob;
    return best;
}

